#include "common.h"
void read_line(const char *prompt, char *buf, size_t size) { printf("%s",prompt); if (!fgets(buf,(int)size,stdin)) { buf[0]='\0'; return; } buf[strcspn(buf,"\r\n")]='\0'; }
int read_int(const char *prompt,int min,int max){char b[64],*e; long v; for(;;){read_line(prompt,b,sizeof b); if(!b[0]){puts("Please enter a number.");continue;} v=strtol(b,&e,10); while(isspace((unsigned char)*e))e++; if(*e=='\0'&&v>=min&&v<=max)return (int)v; printf("Enter a value from %d to %d.\n",min,max);}}
int valid_password(const char *p){int u=0,l=0,d=0,s=0; if(strlen(p)<8)return 0; for(;*p;p++){unsigned char c=(unsigned char)*p;if(isupper(c))u=1;else if(islower(c))l=1;else if(isdigit(c))d=1;else s=1;}return u&&l&&d&&s;}
int valid_journey_date(const char *s){int y,m,d; char extra; struct tm t={0},now={0}; time_t cur=time(NULL),target; if(sscanf(s,"%4d-%2d-%2d%c",&y,&m,&d,&extra)!=3)return 0; t.tm_year=y-1900;t.tm_mon=m-1;t.tm_mday=d;t.tm_hour=12;target=mktime(&t); if(target==(time_t)-1)return 0; struct tm *pt=localtime(&cur); if(!pt)return 0; now=*pt; now.tm_hour=12;now.tm_min=0;now.tm_sec=0; time_t today=mktime(&now); return difftime(target,today)>=-1 && difftime(target,today)<=3*86400 && t.tm_year==y-1900 && t.tm_mon==m-1 && t.tm_mday==d;}
